import io, os, re, json

# Kullaniciya gorunen metinleri cikarir. Kod tanimlayicilari (bosluksuz)
# ve teknik dizeler disarida birakilir.
kok = 'src/app'
dosyalar = []
for d, _, fs in os.walk(kok):
    for f in fs:
        if f.endswith('.tsx'):
            dosyalar.append(os.path.join(d, f).replace('\\', '/'))
dosyalar.append('lib/oturum.tsx')

metinler = {}
for yol in sorted(dosyalar):
    s = io.open(yol, encoding='utf-8').read()
    bulunan = set()
    for m in re.finditer(r"'([^'\n\\]{3,120})'|\"([^\"\n\\]{3,120})\"|`([^`\n\\]{3,120})`", s):
        t = m.group(1) or m.group(2) or m.group(3)
        if ' ' not in t:
            continue
        if re.search(r'[{}<>=;]|https?://|flex|center|space-|^#', t):
            continue
        if not re.search(r'[A-Za-zçğıöşüÇĞİÖŞÜ]', t):
            continue
        bulunan.add(t)
    for m in re.finditer(r'>\s*([^<>{}\n][^<>{}\n]{2,120}?)\s*<', s):
        t = m.group(1).strip()
        if t and re.search(r'[A-Za-zçğıöşüÇĞİÖŞÜ]', t) and ' ' in t:
            bulunan.add(t)
    if bulunan:
        metinler[yol] = sorted(bulunan)

toplam = sum(len(v) for v in metinler.values())
benzersiz = sorted({t for v in metinler.values() for t in v})
print('dosya:', len(metinler), '| toplam:', toplam, '| benzersiz:', len(benzersiz))
io.open('../metinler.json', 'w', encoding='utf-8').write(json.dumps(metinler, ensure_ascii=False, indent=1))
