  update public.check_inler set moderasyon_gizli = true where id = p_check_in_id;

  perform moderasyon.kaydet('icerik_gizlendi', 'check_in', p_check_in_id,
    jsonb_build_object('sahip', v_sahip, 'gerekce', p_gerekce));
end;
