toolUseResult.originalFile:
import { useState } from 'react'
import { supabase } from '../supabase'
import { Hata, hataMetni } from '../ortak/Durum'

type Adim = 'parola' | 'kod'

/**
 * Panel girisi iki asamalidir: parola, ardindan TOTP kodu. Ikinci
 * faktor olmadan alinan oturum `aal1` seviyesindedir ve hicbir
 * moderator RPC'sini cagiramaz - bu kural veritabaninda zorlanir
 * (moderasyon.yetkili_mi), yani bu ekrani atlamak bir sey degistirmez.
 *
 * Ilk kurulumda TOTP kaydi da burada yapilir: enroll bir QR uretir,
 * moderator onu dogrulayici uygulamasina ekler ve ilk kodu girer.
 */
export function Giris({ onGirildi }: { onGirildi: () => void }) {
  const [adim, setAdim] = useState<Adim>('parola')
  const [telefon, setTelefon] = useState('')
  const [parola, setParola] = useState('')
  const [kod, setKod] = useState('')
  const [faktorId, setFaktorId] = useState<string | null>(null)
  const [qr, setQr] = useState<string | null>(null)
  const [hata, setHata] = useState<string | null>(null)
  const [calisiyor, setCalisiyor] = useState(false)

  async function girisYap() {
    setHata(null)
    setCalisiyor(true)
    try {
      const { error } = await supabase.auth.signInWithPassword({
        phone: telefon.trim(),
        password: parola,
      })
      if (error) {
        setHata(error.message)
        return
      }
      await mfaDurumunuOku()
    } catch (e) {
      setHata(hataMetni(e))
    } finally {
      setCalisiyor(false)
    }
  }

  async function mfaDurumunuOku() {
    const { data, error } = await supabase.auth.mfa.listFactors()
    if (error) {
      setHata(error.message)
      return
    }

    const dogrulanmis = data?.totp?.find((f) => f.status === 'verified')
    if (dogrulanmis) {
      setFaktorId(dogrulanmis.id)
      setAdim('kod')
      return
    }

    // Ilk kurulum: yeni bir TOTP faktoru olustur ve QR goster.
    const { data: kayit, error: kayitHatasi } = await supabase.auth.mfa.enroll({
      factorType: 'totp',
    })
    if (kayitHatasi) {
      setHata(kayitHatasi.message)
      return
    }
    setFaktorId(kayit.id)
    setQr(kayit.totp.qr_code)
    setAdim('kod')
  }

  async function koduDogrula() {
    if (!faktorId) return
    setHata(null)
    setCalisiyor(true)
    try {
      const { data: meydan, error: meydanHatasi } =
        await supabase.auth.mfa.challenge({ factorId })
      if (meydanHatasi) {
        setHata(meydanHatasi.message)
        return
      }

      const { error } = await supabase.auth.mfa.verify({
        factorId,
        challengeId: meydan.id,
        code: kod.trim(),
      })
      if (error) {
        setHata(error.message)
        return
      }

      // Oturum artik aal2. Moderator olup olmadigini SUNUCU soyler;
      // panelin kendi karari degil.
      const { data: yetkili } = await supabase.rpc('moderator_muyum')
      if (yetkili !== true) {
        // Sebebi gizlemek bir guvenlik kazanci saglamaz, yalnizca hata
        // ayiklamayi zorlastirir.
        setHata('Bu hesap moderatör değil.')
        await supabase.auth.signOut()
        setAdim('parola')
        return
      }

      onGirildi()
    } catch (e) {
      setHata(hataMetni(e))
    } finally {
      setCalisiyor(false)
    }
  }

  return (
    <div className="giris">
      <h1>Slooin moderasyon</h1>

      {adim === 'parola' && (
        <form
          onSubmit={(e) => {
            e.preventDefault()
            girisYap()
          }}
        >
          <label htmlFor="telefon">Telefon</label>
          <input
            id="telefon"
            value={telefon}
            onChange={(e) => setTelefon(e.target.value)}
            placeholder="+905550000000"
            autoComplete="username"
          />

          <label htmlFor="parola">Parola</label>
          <input
            id="parola"
            type="password"
            value={parola}
            onChange={(e) => setParola(e.target.value)}
            autoComplete="current-password"
          />

          <button type="submit" className="birincil" disabled={calisiyor}>
            {calisiyor ? 'Giriş yapılıyor…' : 'Devam et'}
          </button>
        </form>
      )}

      {adim === 'kod' && (
        <form
          onSubmit={(e) => {
            e.preventDefault()
            koduDogrula()
          }}
        >
          {qr && (
            <div className="qr">
              <p>
                Bu, bu hesap için ilk kurulum. Aşağıdaki kodu doğrulayıcı
                uygulamana ekle, sonra ürettiği altı haneli kodu gir.
              </p>
              <img src={qr} alt="TOTP kurulum kodu" />
            </div>
          )}

          <label htmlFor="kod">Doğrulama kodu</label>
          <input
            id="kod"
            value={kod}
            onChange={(e) => setKod(e.target.value)}
            inputMode="numeric"
            placeholder="123456"
            autoComplete="one-time-code"
          />

          <button type="submit" className="birincil" disabled={calisiyor}>
            {calisiyor ? 'Doğrulanıyor…' : 'Giriş yap'}
          </button>
        </form>
      )}

      <Hata mesaj={hata} />
    </div>
  )
}

input.content:
// Panelin POZITIF yonunu dogrular: gercek bir moderator hesabi, gercek
// TOTP ile aal2 oturumu, ve butun moderator RPC'lerinin calistigi.
//
// Negatif yon (yetkisiz cagri reddediliyor) gorunurluk testlerinde
// senaryo 59'da zaten kapsaniyor. Burada olculen sey onun tersi: kapi
// dogru kimlige ACILIYOR mu.
import { createClient } from '@supabase/supabase-js'
import crypto from 'node:crypto'
import fs from 'node:fs'

const env = Object.fromEntries(
  fs
    .readFileSync(process.argv[2], 'utf8')
    .split('\n')
    .filter((s) => s.includes('='))
    .map((s) => {
      const i = s.indexOf('=')
      return [s.slice(0, i).trim(), s.slice(i + 1).trim()]
    })
)

const URL = env.EXPO_PUBLIC_SUPABASE_URL
const ANON = env.EXPO_PUBLIC_SUPABASE_ANON_KEY
const SERVICE = env.SUPABASE_SERVICE_ROLE_KEY

const TELEFON = '+905550000009'
const PAROLA = 'moderator-test-1234'

let hata = 0
function kontrol(kosul, ad, ek = '') {
  console.log(`  ${kosul ? 'OK  ' : 'HATA'} ${ad}${ek ? ' :: ' + ek : ''}`)
  if (!kosul) hata++
}

// RFC 6238. Supabase enroll base32 bir secret doner.
function base32Coz(s) {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
  let bit = 0
  let deger = 0
  const cikti = []
  for (const ch of s.replace(/=+$/, '').toUpperCase()) {
    const idx = abc.indexOf(ch)
    if (idx === -1) continue
    deger = (deger << 5) | idx
    bit += 5
    if (bit >= 8) {
      cikti.push((deger >>> (bit - 8)) & 0xff)
      bit -= 8
    }
  }
  return Buffer.from(cikti)
}

function totp(secret, zaman = Date.now()) {
  const adim = Math.floor(zaman / 1000 / 30)
  const tampon = Buffer.alloc(8)
  tampon.writeUInt32BE(Math.floor(adim / 2 ** 32), 0)
  tampon.writeUInt32BE(adim >>> 0, 4)
  const ozet = crypto.createHmac('sha1', base32Coz(secret)).update(tampon).digest()
  const ofset = ozet[ozet.length - 1] & 0x0f
  const kod =
    ((ozet[ofset] & 0x7f) << 24) |
    ((ozet[ofset + 1] & 0xff) << 16) |
    ((ozet[ofset + 2] & 0xff) << 8) |
    (ozet[ofset + 3] & 0xff)
  return String(kod % 1_000_000).padStart(6, '0')
}

const yonetici = createClient(URL, SERVICE, { auth: { persistSession: false } })

console.log('\n--- Moderator hesabi hazirlaniyor ---')

// Var olan test moderatorunu bul ya da olustur.
const { data: liste } = await yonetici.auth.admin.listUsers({ perPage: 1000 })
let mod = liste.users.find((u) => u.phone === TELEFON.replace('+', ''))
if (!mod) {
  const { data, error } = await yonetici.auth.admin.createUser({
    phone: TELEFON,
    password: PAROLA,
    phone_confirm: true,
  })
  if (error) {
    console.log('  HATA hesap olusturulamadi ::', error.message)
    process.exit(1)
  }
  mod = data.user
  console.log('  OK   yeni moderator hesabi olusturuldu')
} else {
  await yonetici.auth.admin.updateUserById(mod.id, { password: PAROLA })
  console.log('  OK   mevcut moderator hesabi bulundu, parola tazelendi')
}

// moderatorler satiri: panel kendi moderatorunu ekleyemez (tavuk-yumurta).
const { error: modHata } = await yonetici
  .from('moderatorler')
  .upsert({ kullanici_id: mod.id, rol: 'yonetici' }, { onConflict: 'kullanici_id' })
kontrol(!modHata, 'moderatorler satiri yazildi', modHata?.message)

// PROFIL OLMAMALI (spec karar 56): profili olan moderator kisi
// aramasinda cikar, sikayet edilebilir ve bag grafigine karisir.
const { data: profil } = await yonetici.from('profiller').select('id').eq('id', mod.id)
kontrol((profil ?? []).length === 0, 'moderatorun profil satiri yok (karar 56)')

console.log('\n--- Parola girisi (aal1) ---')
const panel = createClient(URL, ANON, { auth: { persistSession: false } })
const { error: girisHata } = await panel.auth.signInWithPassword({
  phone: TELEFON,
  password: PAROLA,
})
kontrol(!girisHata, 'parola ile giris yapildi', girisHata?.message)

// AAL1 iken kapi KAPALI olmali: moderatorler satiri var ama ikinci
// faktor yok. Karar 56'nin can alici noktasi bu.
const { data: aal1Muyum } = await panel.rpc('moderator_muyum')
kontrol(aal1Muyum === false, 'aal1 oturumda moderator_muyum false (TOTP olmadan gecilmiyor)')

const { error: aal1Rpc } = await panel.rpc('moderasyon_sikayetleri_listele', {})
kontrol(
  (aal1Rpc?.message ?? '').includes('Yetkisiz'),
  'aal1 oturumda moderator RPC reddediliyor',
  aal1Rpc?.message
)

console.log('\n--- TOTP kaydi ve dogrulama (aal2) ---')
const { data: faktorler } = await panel.auth.mfa.listFactors()
let faktorId = faktorler?.totp?.find((f) => f.status === 'verified')?.id
let secret = null

if (!faktorId) {
  const { data: kayit, error: kayitHata } = await panel.auth.mfa.enroll({
    factorType: 'totp',
    friendlyName: 'panel-test-' + Date.now(),
  })
  if (kayitHata) {
    console.log('  HATA TOTP kaydi ::', kayitHata.message)
    process.exit(1)
  }
  faktorId = kayit.id
  secret = kayit.totp.secret
  kontrol(!!kayit.totp.qr_code, 'enroll QR uretti (panel ilk kurulumda bunu gosteriyor)')
  fs.writeFileSync(process.argv[3], secret, 'utf8')
} else {
  secret = fs.readFileSync(process.argv[3], 'utf8').trim()
  kontrol(!!secret, 'kayitli TOTP sirri okundu')
}

const { data: meydan, error: meydanHata } = await panel.auth.mfa.challenge({ factorId })
kontrol(!meydanHata, 'TOTP meydan okumasi olusturuldu', meydanHata?.message)

const { error: dogrulaHata } = await panel.auth.mfa.verify({
  factorId,
  challengeId: meydan.id,
  code: totp(secret),
})
kontrol(!dogrulaHata, 'TOTP kodu dogrulandi (aal2)', dogrulaHata?.message)

console.log('\n--- Kapi ACILDI mi (pozitif yon) ---')
const { data: muyum, error: muyumHata } = await panel.rpc('moderator_muyum')
kontrol(muyum === true, 'aal2 oturumda moderator_muyum true', muyumHata?.message)

const { data: sikayetler, error: listeHata } = await panel.rpc(
  'moderasyon_sikayetleri_listele',
  { p_limit: 10 }
)
kontrol(!listeHata, 'sikayet listesi cagrilabiliyor', listeHata?.message)
console.log(`       (${(sikayetler ?? []).length} sikayet dondu)`)

const { data: arama, error: aramaHata } = await panel.rpc('moderasyon_kullanici_ara', {
  p_metin: 'te',
})
kontrol(!aramaHata, 'kullanici aramasi calisiyor', aramaHata?.message)

let hedefId = (arama ?? [])[0]?.id ?? null
if (hedefId) {
  const { data: detay, error: detayHata } = await panel.rpc('moderasyon_kullanici_detayi', {
    p_kullanici_id: hedefId,
  })
  kontrol(!detayHata, 'kullanici detayi cagrilabiliyor', detayHata?.message)
  kontrol(
    detay && typeof detay === 'object' && 'konusmalar' in detay && 'sikayet_ozeti' in detay,
    'detay karar 64 alanlarini tasiyor (konusmalar, sikayet_ozeti)'
  )
  // Bildirim jetonunun KENDISI donmemeli, yalnizca sayi.
  kontrol(
    typeof detay?.bildirim_cihazi === 'number' && !JSON.stringify(detay).includes('ExponentPushToken'),
    'bildirim jetonu donmuyor, yalnizca cihaz sayisi'
  )
}

console.log('\n--- Moderatore ve kendine islem reddediliyor ---')
const { error: kendineHata } = await panel.rpc('moderasyon_hesabi_askiya_al', {
  p_kullanici_id: mod.id,
  p_bitis: new Date(Date.now() + 86400000).toISOString(),
  p_gerekce: 'test',
})
kontrol(
  (kendineHata?.message ?? '').includes('Kendine islem uygulayamazsin'),
  'moderator kendini askiya alamiyor',
  kendineHata?.message
)

console.log('\n--- Denetim izi ---')
const { data: iz, error: izHata } = await panel.rpc('moderasyon_kayitlarini_listele', {
  p_limit: 20,
})
kontrol(!izHata, 'denetim izi okunabiliyor', izHata?.message)
const eylemler = (iz ?? []).map((k) => k.eylem)
kontrol(
  eylemler.includes('kullanici_detayi_goruntulendi') || !hedefId,
  'kullanici detayi goruntulemesi ize dustu'
)

console.log(`\n${hata === 0 ? 'HEPSI GECTI' : hata + ' DOGRULAMA BASARISIZ'}`)
console.log(`moderator kullanici id: ${mod.id}`)
process.exit(hata === 0 ? 0 : 1)

