// "Error generating QR Code" teshisi: enroll'un hangi varyasyonu
// calisiyor? Panel kodu friendlyName KULLANMIYOR, script kullaniyordu -
// fark buradan gelebilir.
import { createClient } from '@supabase/supabase-js'
import fs from 'node:fs'

const env = Object.fromEntries(
  fs.readFileSync('.env', 'utf8').split('\n').filter((s) => s.includes('=')).map((s) => {
    const i = s.indexOf('=')
    return [s.slice(0, i).trim(), s.slice(i + 1).trim()]
  })
)

const panel = createClient(env.EXPO_PUBLIC_SUPABASE_URL, env.EXPO_PUBLIC_SUPABASE_ANON_KEY, {
  auth: { persistSession: false },
})

const { error: girisHata } = await panel.auth.signInWithPassword({
  phone: '+905550000009',
  password: 'moderator-test-1234',
})
console.log('giris:', girisHata ? 'HATA ' + girisHata.message : 'OK')

// Once mevcut faktorleri gor: yarim kalmis (unverified) bir faktor
// sonraki enroll'u bozabilir.
const { data: mevcut } = await panel.auth.mfa.listFactors()
console.log('mevcut faktorler:', JSON.stringify(mevcut?.all ?? [], null, 1))

for (const f of mevcut?.all ?? []) {
  if (f.status !== 'verified') {
    const { error } = await panel.auth.mfa.unenroll({ factorId: f.id })
    console.log(`  yarim faktor silindi (${f.id}):`, error ? error.message : 'OK')
  }
}

const denemeler = [
  { ad: 'sade (panelin yaptigi)', param: { factorType: 'totp' } },
  { ad: 'issuer ile', param: { factorType: 'totp', issuer: 'Slooin' } },
  { ad: 'friendlyName ile', param: { factorType: 'totp', friendlyName: 'panel' } },
  {
    ad: 'issuer + friendlyName',
    param: { factorType: 'totp', issuer: 'Slooin', friendlyName: 'panel-2' },
  },
]

for (const d of denemeler) {
  const { data, error } = await panel.auth.mfa.enroll(d.param)
  if (error) {
    console.log(`DENEME ${d.ad}: HATA -> ${error.message}`)
  } else {
    console.log(`DENEME ${d.ad}: BASARILI`)
    console.log('   qr var mi   :', !!data.totp?.qr_code)
    console.log('   secret var mi:', !!data.totp?.secret)
    console.log('   uri         :', data.totp?.uri ?? '(yok)')
    // Temizle ki sonraki deneme bozulmasin.
    await panel.auth.mfa.unenroll({ factorId: data.id })
    break
  }
}

