// Teshis sonucu: GoTrue TOTP QR'i uretirken accountName olarak e-postayi
// kullaniyor. Telefon-only hesapta bu alan bos oldugu icin
// "AccountName must be set" hatasi doniyor ve enroll 500 ile patliyor.
//
// Cozum: moderator hesabi E-POSTA ile calisir. Bu zaten daha uygun -
// moderator hesabi uygulamadan ayri (karar 56) ve telefon dogrulama
// SMS maliyeti getiriyor.
import { createClient } from '@supabase/supabase-js'
import crypto from 'node:crypto'
import fs from 'node:fs'

const env = Object.fromEntries(
  fs.readFileSync('.env', 'utf8').split('\n').filter((s) => s.includes('=')).map((s) => {
    const i = s.indexOf('=')
    return [s.slice(0, i).trim(), s.slice(i + 1).trim()]
  })
)

const EPOSTA = 'moderator@slooin.app'
const PAROLA = 'moderator-test-1234'

const yonetici = createClient(env.EXPO_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
  auth: { persistSession: false },
})

let hata = 0
function kontrol(k, ad, ek = '') {
  console.log(`  ${k ? 'OK  ' : 'HATA'} ${ad}${ek ? ' :: ' + ek : ''}`)
  if (!k) hata++
}

function base32Coz(s) {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
  let bit = 0, deger = 0
  const cikti = []
  for (const ch of s.replace(/=+$/, '').toUpperCase()) {
    const idx = abc.indexOf(ch)
    if (idx === -1) continue
    deger = (deger << 5) | idx
    bit += 5
    if (bit >= 8) { cikti.push((deger >>> (bit - 8)) & 0xff); bit -= 8 }
  }
  return Buffer.from(cikti)
}

function totp(secret, zaman = Date.now()) {
  const adim = Math.floor(zaman / 1000 / 30)
  const t = Buffer.alloc(8)
  t.writeUInt32BE(Math.floor(adim / 2 ** 32), 0)
  t.writeUInt32BE(adim >>> 0, 4)
  const o = crypto.createHmac('sha1', base32Coz(secret)).update(t).digest()
  const i = o[o.length - 1] & 0x0f
  const kod = ((o[i] & 0x7f) << 24) | ((o[i + 1] & 0xff) << 16) | ((o[i + 2] & 0xff) << 8) | (o[i + 3] & 0xff)
  return String(kod % 1_000_000).padStart(6, '0')
}

console.log('\n--- Moderator hesabina e-posta ekleniyor ---')
const { data: liste } = await yonetici.auth.admin.listUsers({ perPage: 1000 })
let mod = liste.users.find((u) => u.email === EPOSTA || u.phone === '905550000009')

if (!mod) {
  const { data, error } = await yonetici.auth.admin.createUser({
    email: EPOSTA, password: PAROLA, email_confirm: true,
  })
  kontrol(!error, 'yeni moderator hesabi olusturuldu', error?.message)
  mod = data?.user
} else {
  const { error } = await yonetici.auth.admin.updateUserById(mod.id, {
    email: EPOSTA, email_confirm: true, password: PAROLA,
  })
  kontrol(!error, 'mevcut hesaba e-posta eklendi', error?.message)
}
if (!mod) process.exit(1)

const { error: modHata } = await yonetici
  .from('moderatorler')
