  kontrol(!!secret, 'kayitli TOTP sirri okundu')
} else {
  const { data: kayit, error: kayitHata } = await panel.auth.mfa.enroll({ factorType: 'totp' })
  kontrol(!kayitHata, 'TOTP kaydi olusturuldu (QR uretildi)', kayitHata?.message)
