import type { PropsWithChildren } from 'react'

// Yalnizca WEB ciktisi icin: Expo Router'in urettigi HTML kabugunu
// buradan degistiriyoruz. Native (iOS/Android) derlemelerinde bu dosya
// hic calismaz.
//
// lang="tr" SART. Varsayilan kabuk lang="en" uretiyor; icerik Turkce
// oldugu icin Chrome sayfayi Ingilizce sanip Turkce'ye "cevirmeye"
// calisiyor ve arayuz metinlerini bozuyor. Panelde bu somut olarak
// yasandi: "Şikayetler" basligi ekranda "komiller" olarak gorundu.
