// sagliyor.
export default function Kok({ children }: PropsWithChildren) {
  return (
    <html lang="tr" translate="no">
      <head>
        <meta charSet="utf-8" />
        <meta httpEquiv="X-UA-Compatible" content="IE=edge" />
        <meta
          name="viewport"
          content="width=device-width, initial-scale=1, shrink-to-fit=no"
        />
        <meta name="google" content="notranslate" />
        {/* Expo'nun kendi onerdigi sifirlama: web'de kaydirma
            davranisini native ile ayni hale getiriyor. */}
        <ScrollViewStyleReset />
      </head>
      <body>{children}</body>
    </html>
  )
}

