import { View, StyleSheet, type ViewStyle } from 'react-native'
import { MekanIkonu } from './MekanIkonu'

/**
 * Mekan kapagi: turuncu zemin + beyaz tur ikonu.
 *
 * Karar (kullanici, 2026-08-23): mekanlarin FOTOGRAFI olmayacak. Dis
 * kaynaktan gorsel cekme iptal edildi; kullanicinin check-in fotografi
 * da kapak olamaz cunku o kisi kendi yuzunu yukleyebilir. Kapak, yerin
 * NE OLDUGUNU anlatir. Gercek fotograflar yalnizca ANILARDA.
 *
 * Renk karari da kullanicinin: zemin turuncu, ikon beyaz. Bu, kimlik
 * kuralindaki "turuncu yalnizca eylem icin" cizgisinden bilincli bir
 * sapmadir - kapaklar artik markanin en gorunur yuzeyi oldugu icin
 * turuncu orada tasiniyor. Turuncu'nun eylem anlamini korumak icin
 * BUTONLAR ve canli rozetler daha koyu/dolgun turuncu kullaniyor,
 * kapaklar ise yumusak tonlarda kaliyor.
 *
 * Ton mekan id'sinden TURETILIYOR: ayni mekan hep ayni tonu alir,
 * liste tek duze gorunmez, ve hicbir ag istegi gerekmez.
 */

// Marka turuncusunun cevresinde, birbirine yakin tonlar. Hepsi ayni
// aileden: liste alacali degil, canli gorunuyor.
const TONLAR: [string, string][] = [
  ['#FF8C42', '#F2610C'],
  ['#FFA05C', '#FF6B1A'],
  ['#FF7A2E', '#E85D0F'],
  ['#FFB070', '#FF7A2E'],
  ['#F98C3A', '#DE5A0B'],
  ['#FF9550', '#EF6612'],
]

/** Ayni id her zaman ayni tonu verir; siralama degisse de renk oynamaz. */
function tonSec(id: string): [string, string] {
  let toplam = 0
  for (let i = 0; i < id.length; i++) toplam = (toplam + id.charCodeAt(i)) % 997
  return TONLAR[toplam % TONLAR.length]
}

export function MekanGorseli({
  mekanId,
  tur,
  ikonBoyut = 34,
  style,
  children,
}: {
  mekanId: string
  tur: string
  ikonBoyut?: number
  style?: ViewStyle | ViewStyle[]
  children?: React.ReactNode
}) {
  const ton = tonSec(mekanId)
  return (
    <View style={[stiller.kapsayici, style]}>
      <LinearGradient
        colors={ton}
        start={{ x: 0.15, y: 0 }}
        end={{ x: 0.85, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <View style={stiller.ikonAlani} pointerEvents="none">
        <MekanIkonu tur={tur} boyut={ikonBoyut} renk="#FFFFFF" />
      </View>
      {children}
    </View>
  )
}

