"""Expo web ciktisini (dist/) servis eden kucuk SPA sunucusu.

Neden ozel bir sunucu: expo-router yonlendirmeyi ISTEMCIDE yapiyor.
Duz bir dosya sunucusu kullanilirsa telefonda sayfa yenilendiginde
404 gelir. Burada bilinmeyen her yol index.html'e dusuruluyor.
"""

import os
import sys
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer


class SPA(SimpleHTTPRequestHandler):
    def do_GET(self):
        yol = self.translate_path(self.path)
        if not os.path.exists(yol) or os.path.isdir(yol):
            if not self.path.startswith('/_expo') and '.' not in os.path.basename(self.path):
                self.path = '/index.html'
        return SimpleHTTPRequestHandler.do_GET(self)

    def log_message(self, *args):
        pass  # istek gunlugu gereksiz, ciktiyi kirletiyor


if __name__ == '__main__':
    kok = sys.argv[1]
    port = int(sys.argv[2]) if len(sys.argv) > 2 else 8080
    os.chdir(kok)
    print(f'{kok} -> http://127.0.0.1:{port}', flush=True)
    ThreadingHTTPServer(('127.0.0.1', port), SPA).serve_forever()

