import { supabase } from './supabase'
import { noktayiCoz } from './konum'

export type Mekan = {
  id: string
  ad: string
  tur: string
  /** Semt / mahalle. Kaynakta %97 dolu; yine de null olabilir. */
  semt: string | null
  adres: string | null
  osmId: number | null
  konum: { lat: number; lng: number }
}

type MekanSatiri = {
  id: string
  ad: string
  tur: string
  semt: string | null
  adres: string | null
  osm_id: number | null
  konum: string
}

function satiriMekanaCevir(satir: MekanSatiri): Mekan {
  return {
    id: satir.id,
    ad: satir.ad,
    tur: satir.tur,
    semt: satir.semt ?? null,
    adres: satir.adres,
