import { useState } from 'react'
import { View, Text, TextInput, Pressable, StyleSheet } from 'react-native'
import { useRouter } from 'expo-router'
import { supabase } from '../../../lib/supabase'
import { eFormatinaCevir } from '../../../lib/telefon'

export default function KayitEkrani() {
  const router = useRouter()
  const [telefon, setTelefon] = useState('')
  const [sifre, setSifre] = useState('')
  const [hata, setHata] = useState<string | null>(null)
  const [gonderiliyor, setGonderiliyor] = useState(false)

  async function kayitOl() {
    setHata(null)
    const eFormatli = eFormatinaCevir(telefon)
    if (!eFormatli) {
      setHata('Geçerli bir telefon numarası gir')
      return
    }
    if (sifre.length < 8) {
      setHata('Şifre en az 8 karakter olmalı')
      return
    }

    setGonderiliyor(true)
    const { error } = await supabase.auth.signUp({ phone: eFormatli, password: sifre })
    setGonderiliyor(false)

    if (error) {
      setHata(error.message)
      return
    }
    router.push(`/dogrula?telefon=${encodeURIComponent(eFormatli)}`)
  }

  return (
    <View style={stiller.kapsayici}>
      <Text style={stiller.baslik}>Hesap oluştur</Text>
      <TextInput
        style={stiller.girdi}
        placeholder="05XX XXX XX XX"
        keyboardType="phone-pad"
        value={telefon}
        onChangeText={setTelefon}
      />
      <TextInput
        style={stiller.girdi}
        placeholder="Şifre"
        secureTextEntry
        value={sifre}
        onChangeText={setSifre}
      />
      {hata && <Text style={stiller.hata}>{hata}</Text>}
      <Pressable style={stiller.buton} onPress={kayitOl} disabled={gonderiliyor}>
        <Text style={stiller.butonYazi}>{gonderiliyor ? 'Gönderiliyor...' : 'Kayıt ol'}</Text>
