              // cevaplanamaz; metadata bunu tasimak zorunda.
              gizlilik_metni_surumu: GIZLILIK_METNI_SURUMU,
            }),
          },
        })
      )
    })
    expect(mockRouterPush).toHaveBeenCalledWith('/dogrula?telefon=%2B905551234567')
  })
})

