          <Text style={stiller.ikincilVurgu}>{t('karsilama.girisYap')}</Text>
        </Text>
      </Pressable>

      <Text style={stiller.kucukNot}>{t('karsilama.kucukNot')}</Text>
    </View>
  )
}

