  },

  liste: { paddingTop: bosluk.m, paddingBottom: ALT_GEZINME_PAYI },
  satir: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: bosluk.m,
    paddingVertical: bosluk.m,
    borderBottomWidth: 1,
    borderBottomColor: renk.cizgi,
  },
  fotograf: { width: 44, height: 44, borderRadius: 22 },
  fotografYok: {
    backgroundColor: renk.turuncuZemin,
